import unittest
from access import read_document

class AccessTests(unittest.TestCase):
    def test_tenant_member(self):
        self.assertEqual(read_document({"user_id":"alice","tenant_id":"alpha"},"one"),"alpha sample")
        self.assertEqual(read_document({"user_id":"other-member","tenant_id":"alpha"},"one"),"alpha sample")
    def test_anonymous(self):
        with self.assertRaises(PermissionError):
            read_document(None,"one")
    def test_missing(self):
        with self.assertRaises(KeyError):
            read_document({"user_id":"alice","tenant_id":"alpha"},"absent")

